/* keybinds.c — action defaults plus key<->name mapping (generated table). */
#include "wl/keybinds.h"
#include "wl/util.h"
#include "wl/log.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include "raylib.h" /* KEY_* codes; values are also used in keybindings.txt */

typedef struct {
    int key;
    const char *name;
} WlKeyName;

#include "key_names.inc" /* generated by tools/gen_keymap.py */

typedef struct {
    WlAction act;
    const char *id;
    const char *label;
    int def_key;
} WlActionSpec;

static const WlActionSpec k_actions[] = {
    { WL_ACT_FORWARD,   "forward",   "Walk Forward",     KEY_W },
    { WL_ACT_BACK,      "back",      "Walk Backward",    KEY_S },
    { WL_ACT_LEFT,      "left",      "Strafe Left",      KEY_A },
    { WL_ACT_RIGHT,     "right",     "Strafe Right",     KEY_D },
    { WL_ACT_JUMP,      "jump",      "Jump",             KEY_SPACE },
    { WL_ACT_SNEAK,     "sneak",     "Sneak",            KEY_LEFT_SHIFT },
    { WL_ACT_SPRINT,    "sprint",    "Sprint",           KEY_LEFT_CONTROL },
    { WL_ACT_INVENTORY, "inventory", "Inventory",        KEY_E },
    { WL_ACT_DROP,      "drop",      "Drop Item (Shift: stack)", KEY_Q },
    { WL_ACT_DEBUG,     "debug",     "Debug Overlay",    KEY_F3 },
    { WL_ACT_SCREENSHOT,"screenshot","Screenshot",       KEY_F2 },
    { WL_ACT_PAUSE,     "pause",     "Pause Menu",       KEY_ESCAPE },
};

void wl_keybinds_defaults(WlKeybinds *kb)
{
    for (int i = 0; i < (int)WL_ACT_COUNT; i++)
        kb->key[i] = k_actions[i].def_key;
}

const char *wl_action_label(WlAction a)
{
    if (a >= 0 && a < WL_ACT_COUNT) return k_actions[a].label;
    return "?";
}

const char *wl_action_id(WlAction a)
{
    if (a >= 0 && a < WL_ACT_COUNT) return k_actions[a].id;
    return "?";
}

int wl_action_from_id(const char *id)
{
    if (!id) return WL_ACT_COUNT;
    for (int i = 0; i < (int)WL_ACT_COUNT; i++)
        if (strcmp(k_actions[i].id, id) == 0) return i;
    return WL_ACT_COUNT;
}

const char *wl_key_name(int key)
{
    for (size_t i = 0; i < WL_ARRAY_COUNT(wl_key_name_table); i++)
        if (wl_key_name_table[i].key == key) return wl_key_name_table[i].name;
    return "";
}

/* Normalize "LEFT SHIFT"/"LEFT_SHIFT"/"left shift" to "LEFTSHIFT" for
 * comparison. */
static void normalize_key_name(const char *in, char *out, size_t cap)
{
    size_t o = 0;
    for (const char *p = in; *p && o + 1 < cap; p++) {
        if (*p == ' ' || *p == '_') continue;
        out[o++] = (char)toupper((unsigned char)*p);
    }
    out[o] = '\0';
}

int wl_key_from_name(const char *name)
{
    if (!name || !*name) return -1;
    char want[64];
    normalize_key_name(name, want, sizeof(want));
    if (want[0] == '\0') return -1;

    char have[64];
    for (size_t i = 0; i < WL_ARRAY_COUNT(wl_key_name_table); i++) {
        normalize_key_name(wl_key_name_table[i].name, have, sizeof(have));
        if (strcmp(want, have) == 0) return wl_key_name_table[i].key;
    }
    return -1;
}

bool wl_key_is_bindable(int key)
{
    if (key <= 0) return false;               /* KEY_NULL / negative */
    if (key == KEY_KP_ENTER) return true;     /* still a fine bind */
    for (size_t i = 0; i < WL_ARRAY_COUNT(wl_key_name_table); i++)
        if (wl_key_name_table[i].key == key) return true;
    return false;
}

bool wl_keybinds_load(WlKeybinds *kb, const char *path)
{
    wl_keybinds_defaults(kb);
    if (!wl_file_exists(path)) {
        WL_LOGD("no keybindings file at %s; using defaults", path);
        return true;
    }

    char *data = NULL;
    size_t len = 0;
    if (!wl_read_file(path, &data, &len)) {
        WL_LOGE("cannot read keybindings file %s", path);
        return false;
    }

    int loaded = 0;
    char *save = NULL;
    for (char *line = strtok_r(data, "\n", &save); line; line = strtok_r(NULL, "\n", &save)) {
        char key[64], val[128];
        if (!wl_kv_line(line, key, sizeof(key), val, sizeof(val))) continue;

        int act = wl_action_from_id(key);
        if (act == WL_ACT_COUNT) {
            WL_LOGW("unknown action '%s' in keybindings (ignored)", key);
            continue;
        }
        int kc = wl_key_from_name(val);
        if (kc < 0) {
            /* legacy fallback: raw numeric code */
            long raw;
            if (wl_parse_long(val, &raw) && wl_key_is_bindable((int)raw))
                kc = (int)raw;
        }
        if (kc < 0) {
            WL_LOGW("unknown key '%s' for action '%s' (kept default)", val, key);
            continue;
        }
        kb->key[act] = kc;
        loaded++;
    }
    free(data);
    WL_LOGI("loaded %d keybindings from %s", loaded, path);
    return true;
}

bool wl_keybinds_save(const WlKeybinds *kb, const char *path)
{
    WlStrBuf sb;
    if (!wl_sb_init(&sb, 1024)) return false;

    bool ok = wl_sb_printf(&sb, "# Wildlands keybindings\n");
    ok = ok && wl_sb_printf(&sb, "# action = KEY NAME (names as shown in Settings > Controls)\n");
    for (int i = 0; i < (int)WL_ACT_COUNT && ok; i++) {
        const char *name = wl_key_name(kb->key[i]);
        if (!*name) name = "UNKNOWN";
        ok = ok && wl_sb_printf(&sb, "%s = %s\n", k_actions[i].id, name);
    }

    if (ok) ok = wl_write_file_atomic(path, sb.buf, sb.len);
    wl_sb_free(&sb);

    if (ok) WL_LOGI("saved keybindings to %s", path);
    else    WL_LOGE("failed to save keybindings to %s", path);
    return ok;
}

/* ------------------------------------------------------------------ */
/* held-state query + test seam                                        */
/* ------------------------------------------------------------------ */

static bool s_debug_hold[WL_ACT_COUNT];

bool wl_keybinds_down(const WlKeybinds *kb, WlAction action)
{
    if (action < 0 || action >= WL_ACT_COUNT) return false;
    if (s_debug_hold[action]) return true;
    return IsKeyDown(kb->key[action]);
}

void wl_keybinds_debug_hold(WlAction action, bool held)
{
    if (action >= 0 && action < WL_ACT_COUNT) s_debug_hold[action] = held;
}
